25	const buildBlockListParams = ({ categoryId, search }: BlockListParams) => {
26	  const filter: Record<string, string> = {};
27	
28	  if (categoryId) {
29	    filter['filters[categories][documentId]'] = categoryId as string;
30	  }
31	  if (search) {
32	    filter['filters[name][$containsi]'] = search as string;
33	  }
34	
35	  return Object.keys(filter).length > 0 ? filter : undefined;
36	};
