38	const MarketplaceView = () => {
39	  const user = getUser();
40	  const router = useRouter();
41	  const { categoryId, appId, search } = router.query;
42	  const { ref } = useContainerScrollRestoration({ key: 'marketplace-list' });
43	  const { getSidePanelUrl } = useRouterSidePanel({ key: 'app-management-dialog' });
44	
45	  // 설치는 한 번에 하나만 진행한다. 설치 중에는 다른 블록의 설치 버튼을 비활성화한다.
