58	
59	  const [loadMoreRef, isIntersecting] = useIntersectionObserver<HTMLDivElement>({
60	    rootMargin: '10px',
61	    threshold: 0,
62	  });
63	
64	  useMarketplaceMessage({
65	    onBlockInstalled: ({ blockId }) => {
66	      setInstallingBlockId((prev) => (prev === blockId ? null : prev));
67	    },
68	  });
69	
70	  useEffect(() => {
71	    if (isIntersecting && hasNextPage && !isFetchingNextPage) {
72	      fetchNextPage();
73	    }
74	  }, [isIntersecting, hasNextPage, isFetchingNextPage, fetchNextPage]);
75	
