import type { ReactNode } from 'react';

export type AdVariant =
  | 'banner-small'
  | 'banner-large'
  | 'banner-landing'
  | 'card-large'
  | 'card-medium'
  | 'card-small';

export interface AdItem {
  backgroundColor?: string;
  body?: ReactNode;
  href?: string;
  id?: string | number;
  image?: { alt: string; src: string };
  targets?: string[];
  textColor?: string;
  title: ReactNode;
}

interface AdBaseProps {
  className?: string;
  onVisibilityChange?: (isVisible: boolean) => void;
  variant: AdVariant;
}

export type AdProps = AdBaseProps &
  (
    | {
        dismissible?: boolean;
        items?: never;
        slug: string;
      }
    | {
        dismissible?: never;
        items: AdItem[];
        slug?: never;
      }
  );

