    let resolveSecond: (color: string) => void = () => undefined;
    mockedGetImageIndicatorColor
      .mockImplementationOnce(() => new Promise((resolve) => (resolveFirst = resolve)))
      .mockImplementationOnce(() => new Promise((resolve) => (resolveSecond = resolve)));

    render(
      <Ad
        variant='banner-large'
        items={[
          { title: '첫 번째', image: { alt: '첫 번째', src: '/first.png' } },
          { title: '두 번째', image: { alt: '두 번째', src: '/second.png' } },
        ]}
      />
    );

    act(() => screen.getByRole('button', { name: '2번째 광고' }).click());
    await act(async () => resolveSecond('#333333'));
    await act(async () => resolveFirst('#ffffff'));

    expect(mockedGetImageIndicatorColor).toHaveBeenCalledTimes(2);
    expect(getComputedStyle(screen.getByRole('button', { name: '2번째 광고' })).color).toBe(
      'rgb(51, 51, 51)'
    );
  });

  it('shows the today dismissal button only when a Catalog banner opts in', () => {
