  it('includes the small-banner overlay when selecting a background indicator color', () => {
    render(
      <Ad
        variant='banner-small'
        items={[
          { title: '첫 번째', backgroundColor: '#808080' },
          { title: '두 번째', backgroundColor: '#ffffff' },
        ]}
      />
    );

    expect(getComputedStyle(screen.getByRole('button', { name: '1번째 광고' })).color).toBe(
      'rgb(255, 255, 255)'
    );
  });

  it('includes background alpha when selecting an indicator color', () => {
    render(
      <Ad
        variant='banner-large'
        items={[
          { title: '첫 번째', backgroundColor: 'rgba(0, 0, 0, 0)' },
          { title: '두 번째', backgroundColor: '#ffffff' },
        ]}
      />
    );

    expect(getComputedStyle(screen.getByRole('button', { name: '1번째 광고' })).color).toBe(
      'rgb(51, 51, 51)'
    );
  });

  it('keeps the text color fallback when image brightness analysis fails', async () => {
    mockedGetImageIndicatorColor.mockRejectedValue(new Error('CORS error'));

    render(
      <Ad
        variant='banner-large'
        items={[
          {
            title: '첫 번째',
            image: { alt: '첫 번째', src: '/cors-error.png' },
            textColor: '#abcdef',
          },
          { title: '두 번째' },
        ]}
      />
    );

    await act(async () => undefined);

    expect(getComputedStyle(screen.getByRole('button', { name: '1번째 광고' })).color).toBe(
      'rgb(171, 205, 239)'
    );
  });

  it('ignores a stale image brightness result after moving to another slide', async () => {
    let resolveFirst: (color: string) => void = () => undefined;
    let resolveSecond: (color: string) => void = () => undefined;
    mockedGetImageIndicatorColor
      .mockImplementationOnce(() => new Promise((resolve) => (resolveFirst = resolve)))
      .mockImplementationOnce(() => new Promise((resolve) => (resolveSecond = resolve)));

    render(
      <Ad
        variant='banner-large'
        items={[
          { title: '첫 번째', image: { alt: '첫 번째', src: '/first.png' } },
          { title: '두 번째', image: { alt: '두 번째', src: '/second.png' } },
        ]}
      />
    );

    act(() => screen.getByRole('button', { name: '2번째 광고' }).click());
    await act(async () => resolveSecond('#333333'));
    await act(async () => resolveFirst('#ffffff'));

    expect(mockedGetImageIndicatorColor).toHaveBeenCalledTimes(2);
    expect(getComputedStyle(screen.getByRole('button', { name: '2번째 광고' })).color).toBe(
      'rgb(51, 51, 51)'
    );
  });

  it('shows the today dismissal button only when a Catalog banner opts in', () => {
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ id: 3151, title: '광고' }],
    } as never);
    const { rerender } = render(<Ad slug='home-top' variant='banner-landing' />);

    expect(screen.queryByRole('button', { name: '오늘 하루 보지 않기' })).toBeNull();

    rerender(<Ad slug='home-top' variant='banner-landing' dismissible />);
    expect(screen.getByRole('button', { name: '오늘 하루 보지 않기' })).toBeTruthy();
  });

  it('uses the close button area image brightness color for a single dismissible banner', async () => {
    mockedGetImageIndicatorColor.mockResolvedValue('#ffffff');
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ id: 3151, image: { alt: '어두운 배너', src: '/dark.png' }, title: '광고' }],
    } as never);

    render(<Ad slug='home-top' variant='banner-large' dismissible />);
    await act(async () => undefined);

    expect(mockedGetImageIndicatorColor).toHaveBeenCalledTimes(1);
    expect(screen.getByTestId('icon-cancelSmall').getAttribute('data-color')).toBe('#ffffff');
  });

  it('dismisses only the active Catalog slide for today and moves to the next slide', () => {
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [
        { id: 3151, title: '첫 번째 광고' },
        { id: 3152, title: '두 번째 광고' },
      ],
    } as never);

    render(<Ad slug='home-top' variant='banner-large' dismissible />);

    act(() => screen.getByRole('button', { name: '오늘 하루 보지 않기' }).click());

    expect(screen.queryByText('첫 번째 광고')).toBeNull();
    expect(screen.getByText('두 번째 광고')).toBeTruthy();
    expect(
      JSON.parse(window.localStorage.getItem('sixshop:ad-dismissed:v1:home-top') || '{}')
    ).toHaveProperty('3151');
  });

  it('does not support dismissal for cards or directly supplied items', () => {
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ id: 3151, title: '카드 광고' }],
    } as never);

    const { rerender } = render(<Ad slug='home-card' variant='card-large' dismissible />);
    expect(screen.queryByRole('button', { name: '오늘 하루 보지 않기' })).toBeNull();

    rerender(<Ad variant='banner-small' items={[{ id: 3151, title: '직접 광고' }]} />);
    expect(screen.queryByRole('button', { name: '오늘 하루 보지 않기' })).toBeNull();
  });

  it('restores a dismissed Catalog slide when local midnight passes while mounted', () => {
    const now = new Date(2026, 7, 31, 23, 59, 59);
    const nextMidnight = new Date(2026, 8, 1, 0, 0, 0);
    jest.setSystemTime(now);
    window.localStorage.setItem(
      'sixshop:ad-dismissed:v1:home-top',
      JSON.stringify({ 3151: nextMidnight.getTime() })
    );
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [
        { id: 3151, title: '자정 이후 광고' },
        { id: 3152, title: '상시 광고' },
      ],
    } as never);

    render(<Ad slug='home-top' variant='banner-small' dismissible />);

    expect(screen.queryByText('자정 이후 광고')).toBeNull();
    act(() => jest.advanceTimersByTime(1001));
    expect(screen.getByText('자정 이후 광고')).toBeTruthy();
  });

  it('matches the Figma small banner content layout', () => {
    render(<Ad variant='banner-small' items={[{ title: 'title', body: 'body' }]} />);

    const content = screen.getByText('title').parentElement;

    expect(content && getComputedStyle(content).width).toBe('550px');
    expect(content && getComputedStyle(content).paddingTop).toBe('8px');
    expect(getComputedStyle(screen.getByText('title')).fontSize).toBe('14px');
    expect(getComputedStyle(screen.getByText('body')).marginTop).toBe('-2px');
  });

  it('moves infinitely and resumes rolling five seconds after indicator click', () => {
    render(
      <Ad
        variant='banner-large'
        items={[{ title: '첫 번째' }, { title: '두 번째' }, { title: '세 번째' }]}
      />
    );

    const track = screen.getByTestId('ad-track-banner-large');
    expect(track.style.transform).toBe('translateX(-0%)');

    act(() => jest.advanceTimersByTime(3000));
    expect(track.style.transform).toBe('translateX(-100%)');

    act(() => screen.getByRole('button', { name: '3번째 광고' }).click());
    expect(track.style.transform).toBe('translateX(-200%)');

    act(() => jest.advanceTimersByTime(2000));
    expect(track.style.transform).toBe('translateX(-200%)');

    act(() => jest.advanceTimersByTime(3000));
    expect(track.style.transform).toBe('translateX(-0%)');

    act(() => jest.advanceTimersByTime(1000));
    expect(track.style.transform).toBe('translateX(-0%)');

    act(() => jest.advanceTimersByTime(2000));
    expect(track.style.transform).toBe('translateX(-100%)');

    act(() => screen.getByRole('button', { name: '1번째 광고' }).click());
    expect(track.style.transform).toBe('translateX(-0%)');
  });

  it('ignores a stale rolling callback after a manual move', () => {
    const setTimeoutSpy = jest.spyOn(window, 'setTimeout');

    render(
      <Ad
        variant='banner-large'
        items={[{ title: '첫 번째' }, { title: '두 번째' }, { title: '세 번째' }]}
      />
    );

    const staleRollingCallback = setTimeoutSpy.mock.calls.find(([, delay]) => delay === 3000)?.[0];
    const track = screen.getByTestId('ad-track-banner-large');

    expect(staleRollingCallback).toEqual(expect.any(Function));

    act(() => screen.getByRole('button', { name: '2번째 광고' }).click());
    act(() => (staleRollingCallback as () => void)());

    expect(track.style.transform).toBe('translateX(-100%)');
  });

  it('ignores a stale resume callback after a newer manual move', () => {
    const setTimeoutSpy = jest.spyOn(window, 'setTimeout');

    render(
      <Ad
        variant='banner-large'
        items={[{ title: '첫 번째' }, { title: '두 번째' }, { title: '세 번째' }]}
      />
    );

    const track = screen.getByTestId('ad-track-banner-large');
    act(() => screen.getByRole('button', { name: '2번째 광고' }).click());

    const staleResumeCallback = setTimeoutSpy.mock.calls.find(([, delay]) => delay === 5000)?.[0];

    expect(staleResumeCallback).toEqual(expect.any(Function));

    act(() => screen.getByRole('button', { name: '1번째 광고' }).click());
    act(() => (staleResumeCallback as () => void)());

    expect(track.style.transform).toBe('translateX(-0%)');
  });

  it('slides landing banners with indicators and hides them when only one item remains', () => {
    const { rerender } = render(
      <Ad
        variant='banner-landing'
        items={[{ title: '첫 번째' }, { title: '두 번째' }, { title: '세 번째' }]}
      />
    );

    const track = screen.getByTestId('ad-track-banner-landing');

    expect(screen.queryByRole('button', { name: '이전 광고' })).toBeNull();
    expect(screen.queryByRole('button', { name: '다음 광고' })).toBeNull();

    act(() => jest.advanceTimersByTime(3000));
    expect(track.style.transform).toBe('translateX(-100%)');

    act(() => screen.getByRole('button', { name: '3번째 광고' }).click());
    expect(track.style.transform).toBe('translateX(-200%)');

    act(() => jest.advanceTimersByTime(5000));
    expect(track.style.transform).toBe('translateX(-0%)');

    rerender(<Ad variant='banner-landing' items={[{ title: '하나' }]} />);

    expect(screen.queryByRole('button', { name: /번째 광고/ })).toBeNull();
  });

  it('cancels a pending resume when the item count no longer supports a slider', () => {
    const { rerender } = render(
      <Ad variant='banner-large' items={[{ title: '첫 번째' }, { title: '두 번째' }]} />
    );

    act(() => screen.getByRole('button', { name: '2번째 광고' }).click());
    rerender(<Ad variant='banner-large' items={[{ title: '하나' }]} />);

    act(() => jest.advanceTimersByTime(5000));

    expect(screen.getByText('하나')).toBeTruthy();
    expect(screen.queryByRole('button', { name: '다음 광고' })).toBeNull();
  });

  it('does not render an empty advertisement slot', () => {
    render(<Ad variant='banner-large' items={[]} />);

    expect(screen.queryByTestId('ad-banner-large')).toBeNull();
  });

  it('reports whether an ad is visible', () => {
    const onVisibilityChange = jest.fn();
    const { rerender } = render(
      <Ad variant='banner-small' items={[]} onVisibilityChange={onVisibilityChange} />
    );

    expect(onVisibilityChange).toHaveBeenLastCalledWith(false);

    rerender(
      <Ad
        variant='banner-small'
        items={[{ title: '노출 광고' }]}
        onVisibilityChange={onVisibilityChange}
      />
    );

    expect(onVisibilityChange).toHaveBeenLastCalledWith(true);
  });
});

