    const track = screen.getByTestId(`ad-track-${variant}`);

    expect(indicators).toHaveLength(20);
    expect(getComputedStyle(indicatorGroup).bottom).toBe('0px');
    expect(getComputedStyle(indicatorGroup).gap).toBe('5px');
    expect(getComputedStyle(indicators[0]).width).toBe('24px');
    expect(getComputedStyle(indicators[0]).height).toBe(height);
    expect(getComputedStyle(indicators[0]).position).toBe('relative');
    expect(getComputedStyle(indicators[1]).width).toBe('8px');
    expect(getComputedStyle(indicators[1]).height).toBe(height);
    expect(screen.queryByRole('button', { name: '이전 광고' })).toBeNull();
    expect(screen.queryByRole('button', { name: '다음 광고' })).toBeNull();

    act(() => indicators[19].click());
    expect(track.style.transform).toBe('translateX(-1900%)');

    act(() => jest.advanceTimersByTime(4999));
    expect(track.style.transform).toBe('translateX(-1900%)');

